1	import type { Request } from "express";
2	import { forbidden, unauthorized } from "../errors.js";
3	
4	export function assertAuthenticated(req: Request) {
5	  if (req.actor.type === "none") {
6	    throw unauthorized();
7	  }
8	}
9	
10	export function assertBoard(req: Request) {
11	  if (req.actor.type !== "board") {
12	    throw forbidden("Board access required");
13	  }
14	}
15	
16	export function hasBoardOrgAccess(req: Request) {
17	  if (req.actor.type !== "board") {
18	    return false;
19	  }
20	  if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
21	    return true;
22	  }
23	  return Array.isArray(req.actor.companyIds) && req.actor.companyIds.length > 0;
24	}
25	
26	export function assertBoardOrgAccess(req: Request) {
27	  assertBoard(req);
28	  if (hasBoardOrgAccess(req)) {
29	    return;
30	  }
31	  throw forbidden("Company membership or instance admin access required");
32	}
33	
34	export function assertInstanceAdmin(req: Request) {
35	  assertBoard(req);
36	  if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
37	    return;
38	  }
39	  throw forbidden("Instance admin access required");
40	}
41	
42	export function assertCompanyAccess(req: Request, companyId: string) {
43	  assertAuthenticated(req);
44	  if (req.actor.type === "agent" && req.actor.companyId !== companyId) {
45	    throw forbidden("Agent key cannot access another company");
46	  }
47	  if (req.actor.type === "board" && req.actor.source !== "local_implicit") {
48	    const allowedCompanies = req.actor.companyIds ?? [];
49	    if (!allowedCompanies.includes(companyId)) {
50	      throw forbidden("User does not have access to this company");
51	    }
52	    const method = typeof req.method === "string" ? req.method.toUpperCase() : "GET";
53	    const isSafeMethod = ["GET", "HEAD", "OPTIONS"].includes(method);
54	    if (!isSafeMethod && !req.actor.isInstanceAdmin && Array.isArray(req.actor.memberships)) {
55	      const membership = req.actor.memberships.find((item) => item.companyId === companyId);
56	      if (!membership || membership.status !== "active") {
57	        throw forbidden("User does not have active company access");
58	      }
59	      if (membership.membershipRole === "viewer") {
60	        throw forbidden("Viewer access is read-only");
61	      }
62	    }
63	  }
64	}
65	
66	export function getActorInfo(req: Request) {
67	  assertAuthenticated(req);
68	  if (req.actor.type === "agent") {
69	    return {
70	      actorType: "agent" as const,
71	      actorId: req.actor.agentId ?? "unknown-agent",
72	      agentId: req.actor.agentId ?? null,
73	      runId: req.actor.runId ?? null,
74	    };
75	  }
76	
77	  return {
78	    actorType: "user" as const,
79	    actorId: req.actor.userId ?? "board",
80	    agentId: null,
81	    runId: req.actor.runId ?? null,
82	  };
83	}
